@import "@fontsource-variable/dm-sans";

/* Light (sibling): pale mint paper, the original's bottle green as ink, a deep teal accent. */
:root {
  --background: #eef8f3;
  --foreground: #052824;
  --card: #dff1e9;
  --card-foreground: #052824;
  --popover: #dff1e9;
  --popover-foreground: #052824;
  --primary: #052824;
  --primary-foreground: #b1f9e1;
  --secondary: #dff1e9;
  --secondary-foreground: #052824;
  --muted: #cfe8de;
  --muted-foreground: #24433f;
  --accent: rgba(5, 40, 36, 0.08);
  --accent-foreground: #052824;
  --destructive: #b3261e;
  --destructive-foreground: #ffffff;
  --border: rgba(5, 40, 36, 0.22);
  --input: rgba(5, 40, 36, 0.45);
  --ring: #052824;
  --highlight: #0b6b58;
  --highlight-foreground: #ffffff;
  --glow: #5fe3c4;
  --chart-1: #052824;
  --chart-2: #0b6b58;
  --chart-3: #2fae92;
  --chart-4: #7fd9bf;
  --chart-5: #b9c9b4;
  --sidebar: #dff1e9;
  --sidebar-foreground: #052824;
  --sidebar-primary: #052824;
  --sidebar-primary-foreground: #b1f9e1;
  --sidebar-accent: rgba(5, 40, 36, 0.08);
  --sidebar-accent-foreground: #052824;
  --sidebar-border: rgba(5, 40, 36, 0.22);
  --sidebar-ring: #052824;

  --typeface-body: "DM Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "DM Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 100rem;
  --page-gutter: clamp(1rem, 2.78vw, 2.5rem);
  --section-y: clamp(5rem, 7.8vw, 7rem);
}

/* Dark (faithful): bottle green #052824, mint #b1f9e1 for text, hairlines and buttons,
   near-black green #021d1a for overlays, white for the sparing second voice. */
.dark {
  --background: #052824;
  --foreground: #b1f9e1;
  --card: #021d1a;
  --card-foreground: #b1f9e1;
  --popover: #021d1a;
  --popover-foreground: #b1f9e1;
  --primary: #b1f9e1;
  --primary-foreground: #052824;
  --secondary: #0b352f;
  --secondary-foreground: #b1f9e1;
  --muted: #0d3b35;
  --muted-foreground: #ffffff;
  --accent: rgba(177, 249, 225, 0.15);
  --accent-foreground: #b1f9e1;
  --destructive: #ff8a7a;
  --destructive-foreground: #021d1a;
  --border: rgba(177, 249, 225, 0.3);
  --input: rgba(177, 249, 225, 0.5);
  --ring: #b1f9e1;
  --highlight: #ffffff;
  --highlight-foreground: #052824;
  --glow: #2fd3b0;
  --chart-1: #b1f9e1;
  --chart-2: #2fd3b0;
  --chart-3: #6fb8a4;
  --chart-4: #d9cbb8;
  --chart-5: #ffffff;
  --sidebar: #021d1a;
  --sidebar-foreground: #b1f9e1;
  --sidebar-primary: #b1f9e1;
  --sidebar-primary-foreground: #052824;
  --sidebar-accent: rgba(177, 249, 225, 0.15);
  --sidebar-accent-foreground: #b1f9e1;
  --sidebar-border: rgba(177, 249, 225, 0.3);
  --sidebar-ring: #b1f9e1;
}
